build(dict(S,ch="life-processes-in-animals",topic="nutrition-and-digestion-in-animals",name_en="Nutrition and digestion in animals",name_ta="விலங்குகளில் ஊட்டமும் செரிமானமும்",
 objectives=["Name the steps of nutrition","Trace food through the human digestive system"],
 story=("The journey of a chapati","Sheela chewed a piece of chapati for a long time and noticed it tasted slightly sweet.\n\"Your saliva has started to change the starch into sugar,\" said her teacher. \"Your food now begins a long journey through your body.\""),
 explain=["Animals take in food (ingestion), break it down into simple substances (digestion), absorb the simple substances into the blood (absorption), use them for energy and growth (assimilation), and remove undigested waste (egestion).","In humans, food enters the mouth where teeth chew it and saliva starts digesting starch. It goes down the food pipe (oesophagus) to the stomach, where acid and juices digest it further. In the small intestine digestion ends and digested food is absorbed into the blood. The large intestine absorbs water and the rest leaves as waste.","The liver makes bile that helps digest fats. The pancreas makes juices that digest food. Chewing well, eating on time and washing hands keep the digestive system healthy."],
 terms=["digestion","absorption","small intestine","saliva","bile"],
 narr=[("Nutrition has steps: taking in food, digestion, absorption, using the food and removing waste.","steps of nutrition"),("Food is chewed in the mouth. Saliva begins to digest starch.","mouth"),("In the stomach, acid and juices digest food. In the small intestine digestion ends and food is absorbed.","stomach, small intestine"),("The large intestine absorbs water. The rest leaves as waste.","large intestine")],
 ex=("Where does most absorption of digested food take place?",[("Digestion is completed in the small intestine.","Food is in tiny simple forms."),("The small intestine is long and has a large surface.","This helps absorption."),("So most digested food is absorbed in the small intestine.","It passes into the blood.")]),
 tb=("A friend says food is digested only in the stomach. How will you correct this?",["Digestion starts in the mouth and finishes in the small intestine.","The stomach is only one step."],["Thinking the stomach does all digestion."]),
 summary=["Nutrition: ingestion, digestion, absorption, assimilation, egestion.","Digestion starts in the mouth and ends in the small intestine.","The large intestine absorbs water."],
 q=[("mcq",1,"r1-mouth","Digestion of starch begins in the","mouth",[("stomach","Starch begins in the mouth."),("large intestine","That absorbs water.")],"Saliva acts on starch."),
    ("tf",1,"r1-small","Most absorption of food happens in the small intestine.",True,"True."),
    ("mcq",2,"r2-bile","Bile helps to digest","fats",[("starch","Saliva does that."),("water","Water needs no digestion.")],"The liver makes bile."),
    ("tf",2,"r2-large","The large intestine absorbs water.",True,"True."),
    ("mcq",3,"r3-step","Removing undigested waste is called","egestion",[("ingestion","That is taking in food."),("absorption","That is taking digested food into blood.")],"Waste leaves the body."),
    ("short",3,"r3-organ","Name an organ of the digestive system.",["stomach","mouth","small intestine","large intestine","liver","pancreas","oesophagus","food pipe","intestine"],"Many organs work together."),
    ("mcq",4,"r4-habit","A good habit for digestion is","chewing food well",[("eating very fast","Chew well."),("skipping meals","Eat on time.")],"Chewing starts digestion."),
    ("tf",4,"r4-liver","The liver makes bile.",True,"True.")]))
build(dict(S,ch="life-processes-in-plants",topic="photosynthesis-and-transport-in-plants",name_en="Photosynthesis and transport in plants",name_ta="ஒளிச்சேர்க்கையும் தாவரங்களில் கடத்தலும்",
 objectives=["Write the raw materials and products of photosynthesis","Say how water and food travel in a plant"],
 story=("The pot in the dark","Hari covered one leaf of a potted plant with black paper for three days. After a test with iodine the covered part stayed yellow-brown while the uncovered part turned blue-black.\n\"The leaf made starch only where light fell,\" said his teacher."),
 explain=["Plants make their own food by photosynthesis. Leaves take in carbon dioxide from the air through tiny holes called stomata, roots take in water from the soil, and chlorophyll, the green substance in leaves, captures sunlight energy.","Carbon dioxide + water, in sunlight and chlorophyll, gives glucose (food) and oxygen. Glucose is stored as starch. The oxygen is released into the air.","Water and minerals go up from roots through tubes called xylem. Food made in leaves is carried to all parts through tubes called phloem. Plants also lose water as vapour through stomata, which is called transpiration."],
 terms=["photosynthesis","chlorophyll","stomata","xylem","phloem"],
 narr=[("Plants make food by photosynthesis in their leaves.","photosynthesis"),("Carbon dioxide, water and sunlight go in. Glucose and oxygen come out.","inputs and outputs"),("Water travels up through the xylem. Food travels through the phloem.","xylem and phloem"),("Plants lose water vapour through stomata. This is transpiration.","transpiration")],
 ex=("Why does a plant kept in the dark for many days become weak?",[("Photosynthesis needs sunlight.","Light is an input."),("Without light the leaves cannot make food.","No glucose is formed."),("So the plant becomes weak and may die.","It cannot grow.")]),
 tb=("A friend says plants take their food from the soil. How will you correct this?",["Plants make their own food in the leaves by photosynthesis.","The soil gives water and minerals, not food."],["Thinking soil is plant food."]),
 summary=["Photosynthesis: carbon dioxide + water → glucose + oxygen in sunlight.","Xylem carries water up; phloem carries food.","Transpiration is water loss through stomata."],
 q=[("mcq",1,"r1-green","The green substance in leaves is","chlorophyll",[("starch","That is stored food."),("oxygen","That is a gas.")],"It captures sunlight."),
    ("tf",1,"r1-oxy","Plants release oxygen during photosynthesis.",True,"True."),
    ("mcq",2,"r2-xyl","Water goes up a plant through the","xylem",[("phloem","Phloem carries food."),("stomata","Stomata are holes.")],"Xylem carries water."),
    ("tf",2,"r2-soil","Plants get their food from the soil.",False,"False."),
    ("mcq",3,"r3-sto","Gases enter a leaf through","stomata",[("roots","Roots take water."),("flowers","Flowers make seeds.")],"Stomata are tiny holes."),
    ("short",3,"r3-input","Name one raw material for photosynthesis.",["carbon dioxide","water","sunlight","light"],"Carbon dioxide, water and light."),
    ("mcq",4,"r4-trans","Loss of water vapour from leaves is","transpiration",[("digestion","That is in animals."),("absorption","That is taking in.")],"It cools the plant."),
    ("tf",4,"r4-phl","Phloem carries food to all parts of the plant.",True,"True.")]))
build(dict(S,ch="light-shadows-and-reflections",topic="shadows-and-reflection",name_en="Shadows and reflection",name_ta="நிழலும் எதிரொளிப்பும்",
 objectives=["Explain how shadows form","State the law of reflection"],
 story=("The hand puppets","At night Kavi held his hands in front of a lamp and made a bird on the wall. When he moved his hands closer to the lamp the bird grew bigger.\n\"Shadows change size and sharpness,\" his father said, \"depending on where the object is.\""),
 explain=["Light travels in straight lines. When an opaque object blocks the light a dark area called a shadow forms behind it. Transparent objects make no shadow, translucent ones a light shadow, and opaque ones a dark shadow.","A shadow is bigger when the object is closer to the light source. A pinhole camera uses straight-line light to form an upside-down image.","When light falls on a smooth shiny surface such as a mirror it bounces back. This is reflection. The angle of incidence equals the angle of reflection. A plane mirror forms an image that is the same size, upright and laterally inverted (left and right reversed)."],
 terms=["shadow","reflection","plane mirror","incidence"],
 narr=[("Light travels in straight lines. An opaque object blocks it and makes a shadow.","shadows"),("A shadow grows bigger when the object is nearer the light.","shadow size"),("A mirror bounces light back. This is reflection. The angle of incidence equals the angle of reflection.","reflection"),("A plane mirror gives an upright image with left and right reversed.","mirror image")],
 ex=("Why is the shadow of your hand bigger when it is close to a lamp?",[("The hand blocks more of the spreading light when it is near the lamp.","Light spreads out from the source."),("Light travels in straight lines, so the shadow spreads too.","The shadow follows the light."),("So the shadow is bigger near the lamp and smaller far away.","Distance changes size.")]),
 tb=("A friend says a transparent glass makes a dark shadow. How will you correct this?",["A transparent object lets most light through, so it makes almost no shadow.","Only opaque objects make a dark shadow."],["Mixing transparent and opaque."]),
 summary=["Light travels in straight lines; opaque objects form shadows.","Reflection: angle of incidence equals angle of reflection.","A plane mirror image is upright and laterally inverted."],
 q=[("mcq",1,"r1-shad","A shadow forms when","an opaque object blocks light",[("a mirror is used","That gives reflection."),("light bends","That is refraction.")],"Light travels straight."),
    ("tf",1,"r1-trans","A transparent object makes a dark shadow.",False,"False."),
    ("mcq",2,"r2-refl","Bouncing of light from a surface is","reflection",[("absorption","That is taking in."),("conduction","That is heat.")],"A mirror reflects light."),
    ("tf",2,"r2-law","The angle of incidence equals the angle of reflection.",True,"True."),
    ("mcq",3,"r3-image","The image in a plane mirror is","upright and laterally inverted",[("upside down","It is upright."),("much bigger","It is the same size.")],"Left and right are reversed."),
    ("short",3,"r3-size","When an object is near a lamp, is its shadow bigger or smaller?",["bigger","larger","big"],"A nearer object makes a bigger shadow."),
    ("mcq",4,"r4-straight","Light travels","in straight lines",[("in circles","It goes straight."),("only upward","It goes straight.")],"This is why shadows have sharp edges."),
    ("tf",4,"r4-pin","A pinhole camera forms an upside-down image.",True,"True.")]))
build(dict(S,ch="earth-moon-and-the-sun",topic="eclipses-and-seasons",name_en="Eclipses and seasons",name_ta="கிரகணங்களும் பருவங்களும்",
 objectives=["Explain solar and lunar eclipses","Say why seasons change"],
 story=("Day turns to dusk","During a solar eclipse the sky grew dim at noon and the birds went quiet. Anand watched through special eclipse glasses as the Moon covered the Sun.\n\"Never look at the Sun directly,\" his teacher had warned."),
 explain=["A solar eclipse occurs when the Moon comes between the Sun and the Earth and its shadow falls on the Earth. A lunar eclipse occurs when the Earth comes between the Sun and the Moon and the Earth's shadow falls on the Moon.","We never see an eclipse every month because the Moon's orbit is tilted slightly. Solar eclipses must never be watched with the naked eye, as they can harm the eyes. Special filters are needed.","Seasons change because the Earth's axis is tilted and the Earth goes round the Sun once a year. When the northern part tilts towards the Sun it is summer there and winter in the south, and the other way round half a year later."],
 terms=["solar eclipse","lunar eclipse","axis","season","revolution"],
 narr=[("In a solar eclipse the Moon comes between the Sun and the Earth.","solar eclipse"),("In a lunar eclipse the Earth comes between the Sun and the Moon.","lunar eclipse"),("Never look at the Sun directly, even during an eclipse.","safety"),("Seasons change because the Earth's axis is tilted as it goes around the Sun.","seasons")],
 ex=("Why do we not see a solar eclipse every month?",[("The Moon goes around the Earth every month.","So it passes between us and the Sun often."),("But its path is tilted a little.","Its shadow usually misses the Earth."),("So eclipses happen only when the three are lined up.","This is rare.")]),
 tb=("A friend says seasons occur because the Earth is nearer to the Sun in summer. How will you explain?",["Seasons come from the tilt of the Earth's axis, not distance.","When the northern part tilts towards the Sun it gets more direct sunlight."],["Blaming distance for seasons."]),
 summary=["Solar eclipse: Moon between Sun and Earth.","Lunar eclipse: Earth between Sun and Moon.","Seasons are due to the tilt of the Earth's axis."],
 q=[("mcq",1,"r1-solar","In a solar eclipse the Moon is between","the Sun and the Earth",[("the Earth and the Moon","That makes no sense."),("two stars","No.")],"The Moon blocks the Sun."),
    ("tf",1,"r1-eye","We can watch a solar eclipse with the naked eye safely.",False,"False."),
    ("mcq",2,"r2-lunar","A lunar eclipse happens when","Earth comes between the Sun and the Moon",[("the Moon is between","That is solar."),("the Sun sets","Not related.")],"Earth's shadow falls on the Moon."),
    ("tf",2,"r2-tilt","Seasons change because of the Earth's tilted axis.",True,"True."),
    ("mcq",3,"r3-year","The Earth goes round the Sun once in","a year",[("a day","A day is one spin."),("a month","A month is the Moon's cycle.")],"This is its revolution."),
    ("short",3,"r3-axis","What is tilted to cause the seasons?",["axis","earth's axis","the earth's axis","earths axis"],"The axis is tilted."),
    ("mcq",4,"r4-month","Eclipses are not monthly because the Moon's orbit is","tilted",[("flat","It is tilted."),("circular and equal","It is tilted.")],"Alignment is needed."),
    ("tf",4,"r4-filter","Special filters are needed to watch a solar eclipse.",True,"True.")]))
